If the network contains nn.Linear before the custom op, the compilation with mode="reduce-overhead" changes the result for large inputs.
I tried to use this tutorial to create custom cuda kernel, register it as torch op and plug it into model inference for a speedup. To get a real speedup, I need to compile with mode="reduce-overhead".
All other compilation back-ends work fine (but the resulting model is slow), it also works if the network does not contain nn.Linear, or the size of the input is small enough.
I wrote a set of tests to illustrate the problem. All pass, except test_reduce_overhead_with_linear. It contains compilation with  mode="reduce-overhead", model with nn.Linear and varibale tensor size.
The minimal size to make the test fail depends on the GPU.
For NVIDIA GeForce RTX 2080, it fails around size 4096, for NVIDIA GeForce RTX 4090 it fails at 1024*16 (test_reduce_overhead_with_linear_large).
Tested on torch 2.7.0, 2.5.1 and 2.7.1.
import torch
from torch.testing._internal.common_utils import TestCase
import unittest
import extension_cpp
from torch import nn


class CustomLayer(torch.nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        ret = extension_cpp.ops.mymuladd(x[0], x[0], 0)
        return ret[None, :]


class TestCompilation(TestCase):
    # requires_grad=False
    def sample_input(self, size):
        return torch.randn((1, size), device="cuda", dtype=torch.float32)

    def get_model(self, model_type, size):
        if model_type == "only_custom":
            model = nn.Sequential(
                CustomLayer(),
            )
        elif model_type == "with_linear":
            model = nn.Sequential(
                nn.Linear(
                    in_features=size,
                    out_features=size,
                    device="cuda",
                    dtype=torch.float32,
                ),
                CustomLayer(),
            )
        else:
            raise ValueError("Unsupported model")
        return model

    def compile(self, model, backend):
        if backend == "reduce-overhead":
            compiled = torch.compile(
                model.forward, mode="reduce-overhead", fullgraph=True
            )
        else:
            compiled = torch.compile(model.forward, backend=backend, fullgraph=True)
        return compiled

    def _run_test(self, backend, model_type, size):
        torch.manual_seed(10)
        sample_input = self.sample_input(size)
        model = self.get_model(model_type, size)
        with torch.no_grad():
            model_output = model(sample_input).clone()
            compiled = self.compile(model, backend)
            compiled_model_output = compiled(sample_input).clone()
            print(backend, model_type, size)
            print(model_output)
            print(compiled_model_output)
            assert torch.allclose(
                model_output, compiled_model_output, rtol=0.01, atol=0.01
            )

    def test_inductor_only_custom(self):
        self._run_test("inductor", "only_custom", 4096)

    def test_inductor_with_linear(self):
        self._run_test("inductor", "with_linear", 4096)

    def test_reduce_overhead_only_custom(self):
        self._run_test("reduce-overhead", "only_custom", 4096)

    def test_reduce_overhead_with_linear(self):
        # THIS FAILS
        self._run_test("reduce-overhead", "with_linear", 1024*4)

    def test_reduce_overhead_with_linear_small(self):
        self._run_test("reduce-overhead", "with_linear", 1024*2)

    def test_reduce_overhead_with_linear_large(self):
        # THIS FAILS
        self._run_test("reduce-overhead", "with_linear", 1024*16)

if __name__ == "__main__":
    unittest.main()

